import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.BCI0HzK1.js";const u=JSON.parse('{"title":"学习路径与课时安排","description":"按基础选择学习路径，含课时估算与章节顺序建议。","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"guide/roadmap.md","filePath":"guide/roadmap.md","lastUpdated":1794295584000}'),h={name:"guide/roadmap.md"};function o(i,t,s,l,n,p){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="学习路径与课时安排" tabindex="-1">学习路径与课时安排 <a class="header-anchor" href="#学习路径与课时安排" aria-label="Permalink to &quot;学习路径与课时安排&quot;">​</a></h1><p class="search-summary-seed" aria-hidden="true">按基础选择学习路径，含课时估算与章节顺序建议。</p><p>本页给三条路线，按你现有的经验选一条即可。课时 = 专注阅读 + 跟着把示例敲一遍，不含排错时间。</p><h2 id="路线-a-零基础主线-约-12-小时" tabindex="-1">路线 A：零基础主线（约 12 小时） <a class="header-anchor" href="#路线-a-零基础主线-约-12-小时" aria-label="Permalink to &quot;路线 A：零基础主线（约 12 小时）&quot;">​</a></h2><p>适合：会 JavaScript，没写过服务端。</p><table tabindex="0"><thead><tr><th>顺序</th><th>内容</th><th>难度</th><th>课时</th><th>学完能做什么</th></tr></thead><tbody><tr><td>1</td><td><a href="/nestjs-tutorial/guide/chapters/01-getting-started">01 起步</a></td><td>★☆☆☆☆</td><td>1.5h</td><td>跑起服务、看懂启动日志与目录结构、写出第一个接口</td></tr><tr><td>2</td><td><a href="/nestjs-tutorial/guide/chapters/02-modules-and-di">02 模块化与 DI</a></td><td>★★☆☆☆</td><td>2h</td><td>把代码拆成模块，理解「为什么要注入而不是 new」</td></tr><tr><td>3</td><td><a href="/nestjs-tutorial/guide/chapters/03-request-pipeline">03 请求处理全链路</a></td><td>★★★☆☆</td><td>2.5h</td><td>给接口加上参数校验、统一响应、统一异常与日志</td></tr><tr><td>4</td><td>04 数据层</td><td>★★★☆☆</td><td>2.5h</td><td>用数据库替换内存 Map，会写迁移与事务</td></tr><tr><td>5</td><td>05 配置与环境</td><td>★★☆☆☆</td><td>1h</td><td>多环境配置、密钥不进仓库、启动即校验</td></tr><tr><td>6</td><td>06 认证授权</td><td>★★★★☆</td><td>3h</td><td>登录发令牌、刷新令牌、接口鉴权与越权防护</td></tr></tbody></table><h2 id="路线-b-有-express-koa-经验-约-8-小时" tabindex="-1">路线 B：有 Express / Koa 经验（约 8 小时） <a class="header-anchor" href="#路线-b-有-express-koa-经验-约-8-小时" aria-label="Permalink to &quot;路线 B：有 Express / Koa 经验（约 8 小时）&quot;">​</a></h2><p>跳过环境搭建的细节，重点看 Nest 的分层与扩展点。</p><table tabindex="0"><thead><tr><th>顺序</th><th>内容</th><th>课时</th><th>关注点</th></tr></thead><tbody><tr><td>1</td><td>02 模块化与 DI</td><td>2h</td><td>容器、作用域、循环依赖——与手写 <code>new</code> 的差异</td></tr><tr><td>2</td><td>03 请求处理全链路</td><td>2.5h</td><td>Guard / Interceptor / Filter 与中间件的分工</td></tr><tr><td>3</td><td>04 数据层</td><td>2h</td><td>Repository vs QueryBuilder、事务边界</td></tr><tr><td>4</td><td>06 认证授权</td><td>1.5h</td><td>Guard 组合与「越权」这一类问题</td></tr></tbody></table><h2 id="路线-c-企业落地-约-10-小时" tabindex="-1">路线 C：企业落地（约 10 小时） <a class="header-anchor" href="#路线-c-企业落地-约-10-小时" aria-label="Permalink to &quot;路线 C：企业落地（约 10 小时）&quot;">​</a></h2><p>已经能写 CRUD，目标是「能扛住线上」。</p><table tabindex="0"><thead><tr><th>顺序</th><th>内容</th><th>课时</th><th>关注点</th></tr></thead><tbody><tr><td>1</td><td>06 认证授权</td><td>2h</td><td>越权、令牌轮换、权限模型</td></tr><tr><td>2</td><td>07 缓存与性能</td><td>2h</td><td>失效策略、缓存一致性、N+1</td></tr><tr><td>3</td><td>08 异步与消息</td><td>2h</td><td>队列、幂等、Outbox</td></tr><tr><td>4</td><td><a href="/nestjs-tutorial/guide/chapters/11-observability">11 可观测性</a></td><td>1.5h</td><td>日志、追踪、指标、告警</td></tr><tr><td>5</td><td>12 测试策略</td><td>1.5h</td><td>单测/集成/e2e 分工与门槛</td></tr><tr><td>6</td><td>13 部署与运维</td><td>1h</td><td>容器、优雅关闭、CI</td></tr><tr><td>7</td><td><a href="/nestjs-tutorial/enterprise/">企业级实战</a></td><td>按需</td><td>BFF、订单库存、支付对账</td></tr></tbody></table><h2 id="怎么判断自己「学完了」" tabindex="-1">怎么判断自己「学完了」 <a class="header-anchor" href="#怎么判断自己「学完了」" aria-label="Permalink to &quot;怎么判断自己「学完了」&quot;">​</a></h2><p>每章末尾都有「练习与验收标准」，验收标准是<strong>可执行的检查</strong>，例如：</p><ul><li>能用一个 <code>curl</code> 复现校验失败，并读出错误码与字段名；</li><li>能在不启动数据库的情况下让单测通过（说明分层没漏）；</li><li>能说清一个请求依次经过哪些扩展点、每个扩展点能改什么。</li></ul><p>如果只能「看懂代码」但复现不出来，建议回到该章的最小可跑示例重做一遍。</p><h2 id="学习时的建议" tabindex="-1">学习时的建议 <a class="header-anchor" href="#学习时的建议" aria-label="Permalink to &quot;学习时的建议&quot;">​</a></h2><ol><li><strong>先跑后读</strong>：每章先把示例跑起来，再用文档解释你看到的行为。</li><li><strong>改坏它</strong>：故意去掉 <code>@Injectable()</code>、把 DTO 换成 <code>any</code>、删掉 Guard，观察报错。报错信息本身就是最好的教材。</li><li><strong>记录排查过程</strong>：常见坑一节里列的报错，建议自己复现一次，下次遇到能 30 秒定位。</li><li><strong>别跳过测试</strong>：测试是「企业级做法」里最容易抄走的部分，也是验收标准的主要来源。</li></ol>',18)])])}const b=d(h,[["render",o]]);export{u as __pageData,b as default};
